class Solution {
    /** 3420. Count Non-Decreasing Subarrays After K Operations
     * https://leetcode.com/problems/count-non-decreasing-subarrays-after-k-operations/
     */
public:
    long long countNonDecreasingSubarrays(vector<int>& nums, int k) {
        const int N = nums.size();
        long long res = N;

        /** Memory Limit Exceeded */
        vector<int> ns(nums);
        vector<long long> st(N);
        for (int r = 1; r < N; ++r) {
            const int nc = N - r;
            vector<int> ns1(nc);
            vector<long long> st1(nc);
            for (int c = 0; c < nc; ++c) {
                ns1[c] = max(ns[c], ns[c + 1]);
                st1[c] = st[c] + ns1[c] - nums[c + r];
                if (k >= st1[c]) ++res;
                // cout << ns[c] << ',' << st[c] << ' ';
            }
            ns = move(ns1); st = move(st1);
            // cout << endl;
        }

        // /** Memory Limit Exceeded */
        // vector<vector<pair<int, long long>>> st(N, vector<pair<int, long long>>(N));
        // for (int i = 0; i < N; ++i) st[0][i] = {nums[i], 0};
        // for (int r = 1; r < N; ++r) {
        //     for (int c = r; c < N; ++c) {
        //         st[r][c].first = max(st[r - 1][c - 1].first, st[r - 1][c].first);
        //         st[r][c].second = st[r - 1][c - 1].second + st[r][c].first - nums[c];
        //         if (k >= st[r][c].second) ++res;
        //     }
        // }
        return res;
    }
};

class Solution {
    /** 3420. Count Non-Decreasing Subarrays After K Operations
     * https://leetcode.com/problems/count-non-decreasing-subarrays-after-k-operations/
     */
public:
    long long countNonDecreasingSubarrays(vector<int>& nums, int k) {
        const int N = nums.size();
        long long res = 0, cost = 0;
        deque<int> Q;
        int R = N - 1;
        for (int L = R; L >= 0; --L) {
            while (!Q.empty() && nums[Q.back()] < nums[L]) {
                const long long l = Q.back();
                Q.pop_back();
                const long long r = Q.empty() ? R + 1 : Q.back();
                cost += (r - l) * (nums[L] - nums[l]);
            }
            Q.push_back(L);
            // cout << L << ',' << R << '@' << cost << ':'; for (auto& e: Q) { cout << e << ','; } cout << "->" << endl;
            while (cost > k) {
                cost -= nums[Q.front()] - nums[R];
                if (Q.front() == R) Q.pop_front();
                --R;
            }
            res += R - L + 1;
            // cout << L << ',' << R << '@' << cost << ':'; for (auto& e: Q) { cout << e << ','; } cout << '=' << res << endl;
        }
        return res;
    }
};

